import{_ as t,o as s,c as o,ae as r}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"F5 — Public recovery.crash.detected bus topic + contract test","description":"","frontmatter":{},"headers":[],"relativePath":"plans/tasks/recovery-crash-detected.md","filePath":"plans/tasks/recovery-crash-detected.md"}'),d={name:"plans/tasks/recovery-crash-detected.md"};function a(i,e,c,n,l,h){return s(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="f5-—-public-recovery-crash-detected-bus-topic-contract-test" tabindex="-1">F5 — Public <code>recovery.crash.detected</code> bus topic + contract test <a class="header-anchor" href="#f5-—-public-recovery-crash-detected-bus-topic-contract-test" aria-label="Permalink to &quot;F5 — Public \`recovery.crash.detected\` bus topic + contract test&quot;">​</a></h1><p><strong>Branch:</strong> <code>wbs/recovery-crash-topic</code> (deleted on merge) <strong>PR:</strong> <a href="https://github.com/KooshaPari/HeliosLab/pull/207" target="_blank" rel="noreferrer">#207</a><strong>Merged:</strong> <code>5dcfd385</code> on 2026-09-24 <strong>Worktree:</strong> <code>C:\\Users\\koosh\\agents\\sandbox\\f5-recovery-topic</code><strong>Slice:</strong> 6 (WBS follow-up ladder), F5 (slice-2 follow-up) <strong>Traces to:</strong> F5 in <code>docs/plans/WBS.md</code></p><hr><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>The slice-2 wiring internally subscribes to the watchdog&#39;s crash event via <code>Watchdog.onCrashDetected(callback)</code> and routes it through <code>CrashLoopDetector</code> → <code>SafeMode</code>. That internal path is fully covered by <code>apps/runtime/src/recovery/__tests__/durability-layer.test.ts</code>.</p><p>External consumers (telemetry, dashboards, third-party agents) do not have access to <code>Watchdog.onCrashDetected</code> — they only see the bus API. Until this slice, the <code>recovery.crash.detected</code> event was published to the bus but no <code>bus.subscribe()</code> consumer could actually receive it:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// apps/runtime/src/protocol/bus/emitter.ts (BEFORE F5)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">subscribe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  _topic: string,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  _handler: (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">evt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> EventEnvelope</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Promise</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;void&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">): () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {};   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ← stub. Handlers never invoked.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The <code>CommandBusImpl</code> (used by <code>bus.test.ts</code> / <code>topics.test.ts</code>) had a real implementation, but <code>InMemoryLocalBus</code> — the bus the runtime <em>actually</em> hands to <code>DurabilityLayer</code> — had a stub.</p><h2 id="what-f5-ships" tabindex="-1">What F5 ships <a class="header-anchor" href="#what-f5-ships" aria-label="Permalink to &quot;What F5 ships&quot;">​</a></h2><ol><li><strong><code>InMemoryLocalBus.subscribe()</code></strong> now mirrors <code>CommandBusImpl</code>: handlers are stored in a <code>Map&lt;topic, Array&lt;{ handler, removed }&gt;&gt;</code> and the returned unsubscribe handle removes them. A <code>&quot;*&quot;</code> topic acts as an all-topics subscription, which <code>BusAuditSubscriber</code> already assumed but never got while <code>subscribe()</code> was a stub.</li><li><strong><code>InMemoryLocalBus.publish()</code></strong> delivers each accepted event to matching topic subscribers <em>after</em> the existing eventLog + auditLog pushes, on <strong>both</strong> the lifecycle-start branch and the main branch. The dispatch is extracted into <code>dispatchToSubscribers()</code> so start topics (which take an early <code>return</code>) cannot silently bypass it.</li><li><strong><code>emitter.test.ts</code></strong> (9 tests) pins the bus-level dispatch contract directly. See the contract table below.</li><li><strong><code>recovery-bus-topic.test.ts</code></strong> (9 tests) asserts the crash topic contract end-to-end through the watchdog.</li></ol><h2 id="dispatch-contract" tabindex="-1">Dispatch contract <a class="header-anchor" href="#dispatch-contract" aria-label="Permalink to &quot;Dispatch contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Guarantee</th><th>Mechanism</th></tr></thead><tbody><tr><td>Exact-topic subscribers receive the event</td><td><code>subscribers.get(topic)</code></td></tr><tr><td><code>&quot;*&quot;</code> subscribers receive every event</td><td><code>subscribers.get(WILDCARD_TOPIC)</code>, fanned in after exact-topic handlers</td></tr><tr><td>Handlers are snapshotted before iteration</td><td><code>snapshot</code> array built from handler references, so unsubscribing mid-dispatch cannot skip or reorder delivery (FR-010)</td></tr><tr><td>Synchronous throws are isolated</td><td><code>try { … } catch {}</code> around each handler (FR-009)</td></tr><tr><td>Rejected promises are isolated</td><td><code>void result.catch(() =&gt; {})</code> rejection sink (FR-009)</td></tr><tr><td><strong>Promise-returning handlers are NOT awaited</strong></td><td><code>publish()</code> must never block on a subscriber. <code>Watchdog.handleCrash()</code> awaits <code>publish()</code> <em>before</em> it records the crash with the durability layer, so a subscriber whose promise never settles (stalled telemetry I/O) would otherwise stall crash recovery entirely. Handlers are still invoked synchronously.</td></tr><tr><td>Each subscriber gets a detached envelope</td><td><code>structuredClone(baseEnvelope)</code> per handler, so a consumer mutating <code>payload</code> cannot rewrite what later subscribers see, nor what <code>getEvents()</code> / <code>getAuditRecords()</code> retain</td></tr><tr><td><code>id</code> and <code>ts</code> are forwarded</td><td>Consumers need them to correlate deliveries without re-reading the event log. <code>EventEnvelope</code> does not declare them, so a local <code>DeliveredEventEnvelope</code> intersection type is used rather than widening the shared interface.</td></tr><tr><td><code>destroy()</code> drops all subscriptions</td><td><code>this.subscribers.clear()</code></td></tr></tbody></table><p><code>timestamp</code> is intentionally <strong>not</strong> forwarded: <code>LocalBusEnvelope</code> types it as epoch milliseconds, but <code>validateEnvelope</code> only accepts an ISO-8601 string for that field, so no accepted event can carry a numeric one.</p><h2 id="crash-topic-contract-test" tabindex="-1">Crash-topic contract test <a class="header-anchor" href="#crash-topic-contract-test" aria-label="Permalink to &quot;Crash-topic contract test&quot;">​</a></h2><p><code>recovery-bus-topic.test.ts</code> asserts:</p><ul><li>A heartbeat-timeout crash reaches <code>bus.subscribe(&quot;recovery.crash.detected&quot;, …)</code> with the correct <code>CrashEvent</code> payload.</li><li>A non-graceful exit (code 1) is delivered.</li><li>Graceful exit (code 0) and SIGTERM are <strong>not</strong> delivered.</li><li>SIGKILL is delivered with <code>reason: &quot;SIGNAL&quot;</code>, <code>signal: &quot;SIGKILL&quot;</code>.</li><li>Sequence numbers increase monotonically across consecutive crashes.</li><li>Delivery to bus subscribers happens <strong>before</strong> internal <code>watchdog.onCrashDetected</code> callbacks run, proving the dispatch is synchronous with <code>publish()</code> rather than deferred.</li><li>The unsubscribe handle stops further deliveries.</li><li>A throwing subscriber does not break delivery to others (FR-009).</li><li>Subscribers of <code>recovery.safemode.entered</code> do not receive crash events (topic isolation).</li></ul><h2 id="why-this-is-the-right-scope" tabindex="-1">Why this is the right scope <a class="header-anchor" href="#why-this-is-the-right-scope" aria-label="Permalink to &quot;Why this is the right scope&quot;">​</a></h2><ul><li>The original WBS note for F5 called this a &quot;contract test asserting subscriber-receives-after-watchdog-detection.&quot; That contract was vacuous without the bus plumbing to make it true. F5 fixes the plumbing <strong>and</strong> pins the contract.</li><li><code>DurabilityLayer</code>&#39;s internal <code>Watchdog.onCrashDetected(callback)</code> wiring is preserved unchanged. The public surface (bus API) is additive.</li><li>No new required check on <code>main</code>. The contract test is enforced by the existing <code>Runtime Contract Tests</code> workflow.</li></ul><h2 id="files-touched" tabindex="-1">Files touched <a class="header-anchor" href="#files-touched" aria-label="Permalink to &quot;Files touched&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Change</th></tr></thead><tbody><tr><td><code>apps/runtime/src/protocol/bus/emitter.ts</code></td><td><code>subscribe()</code> stub → real handler registry with <code>&quot;*&quot;</code> support. <code>publish()</code> dispatches to subscribers via the new <code>dispatchToSubscribers()</code> on both the start-topic branch and the main branch. Handlers are not awaited, errors are isolated, and each gets a detached envelope carrying <code>id</code>/<code>ts</code>. <code>destroy()</code> clears the registry.</td></tr><tr><td><code>apps/runtime/src/protocol/bus/emitter.test.ts</code></td><td><strong>New.</strong> 9 tests pinning the bus-level dispatch contract. Also satisfies the <code>Constitution Compliance Validation</code> &quot;Test Coverage&quot; rule, which requires a colocated or mirrored test for each changed <code>.ts</code> source file.</td></tr><tr><td><code>apps/runtime/src/recovery/__tests__/recovery-bus-topic.test.ts</code></td><td>8 tests plus a 9th asserting bus-subscriber-before-internal-handler ordering.</td></tr><tr><td><code>docs/plans/WBS.md</code></td><td>F5 row updated from <code>pending</code> → <code>merged</code> (<a href="https://github.com/KooshaPari/HeliosLab/pull/207" target="_blank" rel="noreferrer">#207</a>, <code>5dcfd385</code>).</td></tr><tr><td><code>docs/plans/tasks/recovery-crash-detected.md</code></td><td>This file.</td></tr></tbody></table><h2 id="files-not-touched" tabindex="-1">Files <strong>not</strong> touched <a class="header-anchor" href="#files-not-touched" aria-label="Permalink to &quot;Files **not** touched&quot;">​</a></h2><ul><li><code>apps/runtime/src/recovery/durability_layer.ts</code> — internal wiring via <code>Watchdog.onCrashDetected(callback)</code> is unchanged. Refactoring <code>DurabilityLayer</code> to subscribe via <code>bus.subscribe()</code> would be cleaner but is out of scope for a slice-6 follow-up.</li><li><code>apps/runtime/src/recovery/safe-mode.ts</code> — same reason. Internal wiring unchanged. The bus API for <code>recovery.safemode.entered</code> and <code>recovery.safemode.exited</code> works automatically as a side-effect of the <code>publish()</code> change.</li><li><code>apps/runtime/src/protocol/bus/types.ts</code> — unchanged. <code>EventEnvelope</code> gained no new fields; the <code>id</code>/<code>ts</code> delivery is handled with a local intersection type in <code>emitter.ts</code>.</li><li><code>apps/runtime/src/protocol/bus/command-bus.ts</code> — already had the correct implementation. Note it <em>does</em> await subscriber promises (line 242), which is the P1 hazard F5 fixed on <code>InMemoryLocalBus</code>. Aligning the two is a follow-up.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>All run on the branch head, after <code>biome check --write</code>:</p><table tabindex="0"><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody><tr><td><code>bun test apps/runtime/src/protocol/bus/emitter.test.ts</code></td><td><strong>9 pass, 0 fail</strong></td></tr><tr><td><code>bun test apps/runtime/src/recovery/__tests__/recovery-bus-topic.test.ts</code></td><td><strong>9 pass, 0 fail</strong></td></tr><tr><td><code>bun test apps/runtime/src/recovery apps/runtime/src/protocol</code></td><td><strong>172 pass, 0 fail</strong></td></tr><tr><td><code>bun run typecheck</code> (tsc --noEmit)</td><td>clean</td></tr><tr><td><code>bunx --package=@biomejs/biome@2.5.11 biome check --write &lt;changed files&gt;</code></td><td>clean, no fixes on final pass</td></tr><tr><td><code>bun run scripts/gate-static-analysis.ts</code></td><td><strong>PASS, 0 findings</strong></td></tr><tr><td><code>bun run scripts/compliance-checker.ts --json &lt;changed files&gt;</code></td><td><strong>passed: true, 0 findings</strong></td></tr><tr><td><code>bun test</code> (full repo, 3146 tests)</td><td><strong>3093 pass, 18 fail, 6 errors</strong> — see the attribution below</td></tr></tbody></table><h3 id="full-suite-failure-attribution" tabindex="-1">Full-suite failure attribution <a class="header-anchor" href="#full-suite-failure-attribution" aria-label="Permalink to &quot;Full-suite failure attribution&quot;">​</a></h3><p>None of the 18 full-repo failures are caused by this slice. Each was checked individually:</p><table tabindex="0"><thead><tr><th>Failing test</th><th>Verdict</th></tr></thead><tbody><tr><td><code>OrphanReconciler.enforceRetention &gt; caps a single call at MAX_RETENTION_DELETIONS_PER_CALL</code></td><td><strong>Pre-existing flake.</strong> I/O-bound: the test creates <code>MAX_RETENTION_DELETIONS_PER_CALL + 50</code> files on disk. It passes in 738ms when the machine is quiet and times out at 5s under parallel load. It imports only <code>checkpoint.js</code> and <code>orphan-reconciler.js</code>, never the bus.</td></tr><tr><td><code>Durability layer integration (slice 3)</code> (7 tests)</td><td><strong>Pre-existing flake, load-sensitive.</strong> All 9 tests in this file pass on both <code>main</code> and this branch when run in isolation. Under the full 298-file parallel run they each exceed the 5s per-test timeout. <code>main</code> also produced a one-off real assertion failure in the SafeMode test on an earlier isolated run, confirming the file is timing-fragile independent of this change.</td></tr><tr><td><code>vitepress config exists</code></td><td><strong>Pre-existing.</strong> Reproduces on <code>main</code> at <code>d6e23f37</code>.</td></tr><tr><td><code>Worktree helpers &gt; computeWorktreePath joins correctly</code></td><td>Pre-existing, path-separator dependent on Windows.</td></tr><tr><td><code>Latency Benchmarks</code>, <code>Ghostty Capabilities</code>, <code>Performance</code> (3 tests)</td><td>Pre-existing timing assertions.</td></tr></tbody></table><p>The F5-relevant suites are stable and fully green:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bun test apps/runtime/src/recovery apps/runtime/src/protocol</span></span>
<span class="line"><span>  172 pass, 0 fail</span></span></code></pre></div><h2 id="mutation-testing" tabindex="-1">Mutation testing <a class="header-anchor" href="#mutation-testing" aria-label="Permalink to &quot;Mutation testing&quot;">​</a></h2><p>11 mutations were applied to <code>emitter.ts</code>, each reintroducing one behavioral bug, and each was required to cause at least one test to fail. <strong>All 11 were caught</strong> (0 escaped).</p><table tabindex="0"><thead><tr><th>#</th><th>Mutation</th><th>Result</th></tr></thead><tbody><tr><td>M1</td><td><code>await</code> subscribers instead of detaching them (reintroduces the P1 hang)</td><td>CAUGHT (1 fail)</td></tr><tr><td>M2</td><td>Start topics skip dispatch (the original P2 bug)</td><td>CAUGHT (1 fail)</td></tr><tr><td>M3</td><td>Main branch skips dispatch</td><td>CAUGHT (14 fail)</td></tr><tr><td>M4</td><td>Drop <code>id</code> from the delivered envelope</td><td>CAUGHT (2 fail)</td></tr><tr><td>M5</td><td>Drop <code>ts</code> from the delivered envelope</td><td>CAUGHT (1 fail)</td></tr><tr><td>M6</td><td>Share one envelope instead of cloning per subscriber</td><td>CAUGHT (1 fail)</td></tr><tr><td>M7</td><td>No <code>&quot;*&quot;</code> wildcard routing</td><td>CAUGHT (1 fail)</td></tr><tr><td>M8</td><td><code>destroy()</code> becomes a no-op</td><td>CAUGHT (1 fail)</td></tr><tr><td>M9</td><td><code>unsubscribe()</code> stops splicing the entry out</td><td>CAUGHT (2 fail)</td></tr><tr><td>M10</td><td>Synchronous subscriber errors escape <code>publish()</code></td><td>CAUGHT (1 fail)</td></tr><tr><td>M11</td><td>No snapshot (iterate the live list)</td><td>CAUGHT (1 fail)</td></tr></tbody></table><p>Two mutations initially escaped during harness development and drove real test improvements rather than harness tweaks:</p><ul><li><strong>M8 (destroy)</strong> escaped because the original test unsubscribed before calling <code>destroy()</code>, leaving nothing to clear. The test now registers a fresh subscriber before <code>destroy()</code>.</li><li><strong>M6 (shared envelope)</strong> initially had no test at all. A dedicated &quot;does not alias the logged envelope&quot; test was added.</li></ul><h2 id="review-threads-addressed" tabindex="-1">Review threads addressed <a class="header-anchor" href="#review-threads-addressed" aria-label="Permalink to &quot;Review threads addressed&quot;">​</a></h2><p>Six review threads were open on the first push. All are resolved by the changes above:</p><table tabindex="0"><thead><tr><th>Thread</th><th>Finding</th><th>Resolution</th></tr></thead><tbody><tr><td>P1 ×2 (<code>emitter.ts:240</code>)</td><td>Awaiting a subscriber promise that never settles hangs <code>publish()</code>, and therefore stalls crash recovery</td><td>Handlers are invoked but not awaited; a rejection sink isolates async failures (M1)</td></tr><tr><td>P2 ×2 (<code>emitter.ts:205</code>)</td><td>Start topics return before reaching the dispatch block, so subscribers silently miss operation starts</td><td>Dispatch extracted to <code>dispatchToSubscribers()</code> and called on both branches (M2, M3)</td></tr><tr><td>Data integrity (<code>emitter.ts:221</code>)</td><td>Reconstructed envelope drops <code>id</code> and <code>ts</code>, blocking correlation</td><td><code>id</code>/<code>ts</code> forwarded via <code>DeliveredEventEnvelope</code> (M4, M5)</td></tr><tr><td>Maintainability (<code>recovery-bus-topic.test.ts:153</code>)</td><td>Increasing sequence numbers does not prove synchronous delivery</td><td>New test records the order of a bus subscriber versus a <code>watchdog.onCrashDetected</code> callback and asserts subscriber-first</td></tr></tbody></table><p>Additionally, CodeAnt flagged that a subscriber could mutate retained audit records. Each subscriber now receives its own <code>structuredClone</code> (M6).</p><h2 id="post-merge-follow-ups-out-of-scope-here" tabindex="-1">Post-merge follow-ups (out of scope here) <a class="header-anchor" href="#post-merge-follow-ups-out-of-scope-here" aria-label="Permalink to &quot;Post-merge follow-ups (out of scope here)&quot;">​</a></h2><ol><li><strong>Align <code>CommandBusImpl.publish()</code> with the no-await contract.</strong><code>command-bus.ts:242</code> still does <code>await handler(event)</code>, so a hanging subscriber stalls the command bus. <code>InMemoryLocalBus</code> no longer has that hazard; the two implementations should agree.</li><li><strong>Refactor <code>DurabilityLayer</code> to subscribe via the bus.</strong> Today the layer wires <code>Watchdog.onCrashDetected(callback)</code> directly. A future slice could migrate this to <code>bus.subscribe(&quot;recovery.crash.detected&quot;, …)</code> so the public topic is the single wiring path. Not done here because <code>CrashLoopDetector.recordCrash(timestamp)</code> needs a number, not a <code>CrashEvent</code> object.</li><li><strong><code>recovery.safemode.entered</code> / <code>recovery.safemode.exited</code> contract test.</strong> Now that <code>subscribe()</code> works, those topics are also publicly observable. A future slice could add a <code>safe-mode-bus.test.ts</code> mirroring the structure of <code>recovery-bus-topic.test.ts</code>.</li><li><strong>Widen the shared <code>EventEnvelope</code> interface with <code>id</code>/<code>ts</code>.</strong> F5 uses a local intersection type to avoid a cross-cutting API change.</li><li><strong>The compliance checker&#39;s reverse lookup cannot match ESM imports.</strong><code>testImportsSourceFile()</code> builds patterns like <code>from [&#39;&quot;].*emitter[&#39;&quot;]</code>, which never match <code>from &quot;./emitter.js&quot;</code>. Every changed <code>.ts</code> file therefore needs a colocated test even when an existing test already imports it through the barrel. Fixing the pattern would remove that false positive at its source.</li></ol>`,41)])])}const b=t(d,[["render",a]]);export{p as __pageData,b as default};
